// План specs/payments-portal.md 3.3 (#ec42a8, связь #5e4fe6). Pre-Prod, preprod-ttp, Stripe test. @writes @stripe-test.
// ПО УМОЛЧАНИЮ ПРОПУЩЕН: тест реально возвращает $1 (тестовый Stripe, необратимо) и расходует платёж 4242 — запуск только по явной
// команде: QA_ALLOW_REFUND=1 (разрешён пользователем 17.11 на этапе проверки тикета; в регрессе — по решению пользователя).
// Ожидаемое: после Refund → toast «The payment was refunded.» + строка «$1 · клиент» (не alert), статус строки Refunded, кнопки Refund
// у неё нет, Total Transactions уменьшился на 1 (#5e4fe6: возвращённые в итоги не входят).
import { test, expect } from '../../fixtures';
import { ROLE, kpi, openPortal, parseMoney, txRows } from './portal-helpers';

test.describe('Payment Portal — Refund result (#ec42a8)', () => {
  test.skip(process.env.QA_ALLOW_REFUND !== '1', 'пишущий тест: реальный Refund $1 в тестовом Stripe — только при QA_ALLOW_REFUND=1');

  test('Refund $1 → success toast (not alert), status Refunded, totals exclude the refunded payment #ec42a8 @desktop @writes @stripe-test', async ({ asUser }) => {
    const page = await asUser(ROLE);
    let systemDialogs = 0;
    page.on('dialog', async (d) => { systemDialogs++; await d.dismiss(); });
    await openPortal(page);

    const totalBefore = Number(await kpi(page, 'Total Transactions'));
    const amountBefore = parseMoney(await kpi(page, 'Total Amount'));
    const refundedBefore = await txRows(page).filter({ hasText: 'Refunded' }).count();

    const row = txRows(page)
      .filter({ has: page.getByRole('button', { name: 'Refund', exact: true }) })
      .filter({ hasText: /\$1(\.00)?(?!\d)/ })
      .first();
    await expect(row, 'есть возвращаемый платёж на $1 (Succeeded)').toBeVisible();
    await row.getByRole('button', { name: 'Refund', exact: true }).click();

    const dialog = page.getByRole('dialog').or(page.getByRole('alertdialog')).filter({ hasText: 'Refund this payment?' });
    await expect(dialog).toBeVisible();
    await dialog.getByRole('button', { name: 'Refund', exact: true }).click();

    const toast = page.locator('li, [role="status"]').filter({ hasText: 'The payment was refunded.' }).first();
    await expect(toast).toBeVisible({ timeout: 30_000 });
    await expect(toast).toContainText(/\$1\b.*TTP Customer/);
    expect(systemDialogs, 'результат — toast, не системный alert').toBe(0);

    await expect(txRows(page).filter({ hasText: 'Refunded' })).toHaveCount(refundedBefore + 1, { timeout: 30_000 });
    await expect.poll(async () => Number(await kpi(page, 'Total Transactions')), { timeout: 30_000 }).toBe(totalBefore - 1);
    expect(parseMoney(await kpi(page, 'Total Amount'))).toBe(amountBefore - 1);
  });
});
